COPY_DIRECT_HOST="ep-restless-tooth-b42czg5d.c-6.us-east-2.aws.neon.tech"
COPY_POOLED_HOST="ep-restless-tooth-b42czg5d-pooler.c-6.us-east-2.aws.neon.tech"
