trap 'DATABASE_URL_VALUE=""; clear_clipboard' EXIT

to_clipboard() {
  if command -v pbcopy >/dev/null 2>&1; then
    printf '%s' "$1" | pbcopy
    printf '  %s✓ copied%s %s to the clipboard (not shown)\n' "$GREEN" "$RESET" "$2"
  else
    warn "No pbcopy. This wizard needs macOS to hand over secrets without showing them."
    exit 1
  fi
}

clear_clipboard() {
  command -v pbcopy >/dev/null 2>&1 && printf '' | pbcopy
  return 0
}

required_answer() {
  local key="$1" prompt="$2"
  while true; do
    ask "$key" "$prompt"
    [[ "${!key}" =~ [^[:space:]] ]] && break
    warn "Enter an observation, or enter 'unknown'."
  done
  write_env "$key" "${!key}"
}

check() {
  local key="$1" question="$2"
  if confirm "$question"; then
    write_env "$key" "passed"
  else
    INCOMPLETE=1
    required_answer "${key}_NOTE" "What happened instead (no secrets)?"
    write_env "$key" "blocker"
  fi
}

fingerprint() {
  local key="$1" prompt="$2"
  while true; do
    ask "$key" "$prompt"
    [[ "${!key}" =~ ^([0-9a-f]{32}|blocker)$ ]] && break
    warn "Paste the 32-character fingerprint, or enter 'blocker' if the query failed."
  done
  write_env "$key" "${!key}"
}

sha() { printf '%s' "$1" | shasum -a 256 | cut -d' ' -f1; }

local_value() {
  [[ -f "$REPO_ROOT/.env.local" ]] || return 0
  { grep -E "^$1=" "$REPO_ROOT/.env.local" || true; } | tail -n1 | cut -d= -f2- | sed -e "s/^['\"]//" -e "s/['\"]$//"
}

